"""Delivery zones by New Zealand postcode range, as the courier contract files them.

Ranges are inclusive and do not overlap; a postcode no range holds has no
delivery zone.
"""

from dataclasses import dataclass

RURAL_SURCHARGE_CENTS = 650


@dataclass(frozen=True)
class DeliveryZone:
    start: str
    end: str
    zone: str
    courier: str
    min_days: int
    rural: bool


def zone_for(postcode: str) -> DeliveryZone | None:
    if not postcode.isdigit():
        return None
    value = int(postcode)
    for zone in ZONES:
        if int(zone.start) <= value <= int(zone.end):
            return zone
    return None


